def validate_request_data(data):
    """Validate the shape of an incoming API request payload.

    Request payloads must be dictionaries with string keys. The validated
    payload is returned unchanged so callers can pass it directly onward.
    """
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    invalid_key = next((key for key in data if not isinstance(key, str)), None)
    if invalid_key is not None:
        raise TypeError("data keys must be strings")

    return data


def handle_request(data, legacy_mode=False):
    """Validate an incoming API request payload before processing it.

    ``legacy_mode`` temporarily supports older clients whose payloads cannot
    yet be validated. New callers should leave it disabled.
    """
    if not legacy_mode:
        validate_request_data(data)

    return process(data)

